    // Autonomous Digestion Control
    bool TriggerAutonomousDigestion(const std::wstring& filepath);
    bool ValidateDigestionPrerequisites();
    bool MonitorDigestionExecution(DWORD taskId, DWORD timeoutMs = 30000);
    
    // State Queries
