// ============================================================================
// AgentMemory - Persistent Learning and Pattern Recognition
// ============================================================================

enum class ExecutionOutcome {
    SUCCESS,
    FAILURE,
    PARTIAL_SUCCESS,
    TIMEOUT,
    CANCELLED
};

struct ExecutionRecord {
    std::string actionType;
    ExecutionOutcome outcome;
    int executionTimeMs;
    std::string errorMessage;
    std::chrono::system_clock::time_point timestamp;
    std::string context;
    int confidenceBefore;
    int confidenceAfter;
};

struct PatternRecord {
    std::string patternName;
    std::string description;
    int frequency;
    double successRate;
    std::vector<std::string> associatedActions;
    std::chrono::system_clock::time_point lastSeen;
};

class AgentMemory {
private:
    sqlite3* m_db;
    std::string m_dbPath;
    std::unordered_map<std::string, PatternRecord> m_patternCache;
    std::mutex m_mutex;

    bool initializeDatabase();
    bool createTables();
    bool loadPatterns();

public:
    AgentMemory();
    ~AgentMemory();

    bool initialize(const std::string& projectRoot);
    void recordExecution(const std::string& actionType, ExecutionOutcome outcome,
                        int executionTimeMs, const std::string& errorMessage = "",
                        const std::string& context = "");
    void updatePattern(const std::string& patternName, bool success);
    double getSuccessRate(const std::string& actionType) const;
    double getPatternSuccessRate(const std::string& patternName) const;
    std::vector<std::string> getLearnedPatterns() const;
    int getExecutionCount(const std::string& actionType) const;
    std::vector<ExecutionRecord> getRecentExecutions(int limit = 10) const;
    void cleanupOldRecords(int daysOld = 30);
};

// ============================================================================
// HierarchicalPlanner - Complex Task Decomposition and Planning
// ============================================================================

enum class TaskComplexity {
    SIMPLE,
    MODERATE,
    COMPLEX,
    VERY_COMPLEX
};

struct SubGoal {
    std::string description;
    std::vector<std::string> requiredActions;
    std::vector<std::string> dependencies;
    TaskComplexity complexity;
    int estimatedTimeMinutes;
    std::vector<std::string> successCriteria;
};

struct PlanningContext {
    std::string projectRoot;
    std::vector<std::string> availableTools;
    std::map<std::string, double> toolSuccessRates;
    std::vector<std::string> recentPatterns;
    int timeBudgetMinutes;
    TaskComplexity maxComplexity;
};

class HierarchicalPlanner {
private:
    AgentMemory* m_memory;
    std::mutex m_mutex;

    std::vector<SubGoal> decomposeComplexTask(const std::string& task, const PlanningContext& context);
    std::vector<SubGoal> decomposeModerateTask(const std::string& task, const PlanningContext& context);
    bool validateDecomposition(const std::vector<SubGoal>& subGoals);
    void optimizeDecomposition(std::vector<SubGoal>& subGoals, const PlanningContext& context);

public:
    HierarchicalPlanner();
    void setMemory(AgentMemory* memory) { m_memory = memory; }

    std::vector<SubGoal> decomposeWish(const std::string& wish, const PlanningContext& context);
    std::vector<std::string> getDependencyChain(const SubGoal& goal) const;
    int estimateTotalTime(const std::vector<SubGoal>& subGoals) const;
    TaskComplexity assessComplexity(const std::string& task) const;
};

// ============================================================================
// AgentSelfReflection - Error Analysis and Self-Improvement
// ============================================================================

enum class ErrorType {
    PERMISSION_DENIED,
    FILE_NOT_FOUND,
    NETWORK_ERROR,
    TIMEOUT,
    INVALID_SYNTAX,
    DEPENDENCY_MISSING,
    RESOURCE_EXHAUSTED,
    UNKNOWN
};

struct ErrorAnalysis {
    ErrorType type;
    std::string rootCause;
    int severity; // 1-10
    std::string impact;
    bool recoverable;
    std::vector<std::string> suggestedFixes;
};

struct AlternativeApproach {
    std::string description;
    std::vector<std::string> actions;
    double confidence;
    double expectedSuccessRate;
    int estimatedTimeMinutes;
};

struct ConfidenceAdjustment {
    std::string actionType;
    double oldConfidence;
    double newConfidence;
    std::string reason;
};

class AgentSelfReflection {
private:
    AgentMemory* m_memory;
    std::unordered_map<std::string, double> m_confidenceLevels;
    std::mutex m_mutex;

    ErrorType classifyError(const std::string& errorMessage) const;
    std::vector<std::string> generateFixes(ErrorType errorType, const std::string& context) const;
    double calculateConfidence(const std::string& actionType) const;

public:
    AgentSelfReflection();
    void setMemory(AgentMemory* memory) { m_memory = memory; }

    ErrorAnalysis analyzeError(const std::string& actionType, const std::string& errorMessage,
                              const std::string& context);
    std::vector<AlternativeApproach> generateAlternatives(const std::string& actionType,
                                                         const ErrorAnalysis& analysis,
                                                         const std::string& context);
    bool shouldEscalateToHuman(const ErrorAnalysis& analysis,
                              const std::vector<AlternativeApproach>& alternatives) const;
    ConfidenceAdjustment adjustConfidence(ExecutionOutcome outcome, const std::string& actionType,
                                        int executionTimeMs);
    double getConfidence(const std::string& actionType) const;
    void learnFromExecution(const std::string& actionType, bool success, int executionTimeMs,
                           const std::string& errorMessage = "");
};

