// ============================================================================
// AutonomousDecisionEngine - Graduated Autonomy and Risk Management
// ============================================================================

enum class AutonomyLevel {
    SUPERVISED,      // Require approval for all actions
    SEMI_AUTONOMOUS, // Low-risk actions automatic, high-risk require approval
    FULLY_AUTONOMOUS // All actions automatic with monitoring
};

enum class RiskLevel {
    LOW,
    MEDIUM,
    HIGH,
    CRITICAL
};

struct DecisionContext {
    std::string wish;
    std::vector<std::string> availableActions;
    ArchitectureOverview projectContext;
    std::string urgency; // "low", "medium", "high"
    std::string complexity; // "low", "medium", "high"
    std::map<std::string, double> actionSuccessRates;
};

struct DecisionOutcome {
    bool requiresApproval;
    std::string reasoning;
    AutonomyLevel autonomyLevel;
    std::vector<std::string> approvedActions;
    std::vector<std::string> requiresApprovalActions;
    double confidence;
};

struct RiskFactor {
    std::string factor;
    RiskLevel level;
    double weight;
    std::string description;
};

class AutonomousDecisionEngine {
private:
    AutonomyLevel m_currentLevel;
    AgentMemory* m_memory;
    std::map<std::string, double> m_riskThresholds;
    std::mutex m_mutex;

    std::vector<RiskFactor> assessRisks(const std::string& action, const DecisionContext& context) const;
    double calculateRiskScore(const std::vector<RiskFactor>& risks) const;
    bool isActionLowRisk(const std::string& action, const DecisionContext& context) const;

public:
    AutonomousDecisionEngine();
    void setMemory(AgentMemory* memory) { m_memory = memory; }

    void setAutonomyLevel(AutonomyLevel level) { m_currentLevel = level; }
    AutonomyLevel getAutonomyLevel() const { return m_currentLevel; }

    DecisionOutcome makeDecision(const DecisionContext& context);
    double getMaxRiskThreshold() const;
    void adjustRiskThresholds(const std::string& actionType, double newThreshold);
};

