    ActionExecutionResult handleRunBuild(const Action& action);
    ActionExecutionResult handleExecuteTests(const Action& action);
    ActionExecutionResult handleCommitGit(const Action& action);
    ActionExecutionResult handleInvokeCommand(const Action& action);
    ActionExecutionResult handleRecursiveAgent(const Action& action);
    ActionExecutionResult handleQueryUser(const Action& action);

