    uint32_t calculateCRC32(size_t offset, size_t size) const;
    bool parseTensorMetadata();
    bool rebuildTensorDependencyMap();

    void* m_modelPtr = nullptr;
    size_t m_modelSize = 0;
    bool m_attached = false;
