// [HEADER] compression\custom_zlib_wrapper.h
// FILE: D:\rawrxd\include\compression\custom_zlib_wrapper.h
// ============================================================================

// ============================================================================
// Custom ZLIB Wrapper - Qt/C++ interface to MASM compression
// Production-ready implementation with comprehensive error handling
// ============================================================================

// [GUARD] #ifndef CUSTOM_ZLIB_WRAPPER_H
// [GUARD] #define CUSTOM_ZLIB_WRAPPER_H

#include <QByteArray>
#include <QString>
#include <QDebug>
// [SYSINCLUDE] #include <cstdint>

// ============================================================================
// External MASM function declarations
// ============================================================================
extern "C" {
    int64_t CustomZlibCompress(const uint8_t* input, uint64_t inputSize,
                               uint8_t* output, uint64_t outputSize);
    
    int64_t CustomZlibDecompress(const uint8_t* input, uint64_t inputSize,
                                 uint8_t* output, uint64_t outputSize);
    
    uint64_t CustomZlibGetCompressedSize(uint64_t uncompressedSize);
    
    int64_t CustomZlibGetDecompressedSize(const uint8_t* compressed, uint64_t compressedSize);
    
    int64_t CustomZlibInit(void* context, uint64_t contextSize);
    
    int64_t CustomZlibFree(void* context);
}

// ============================================================================
// CustomZlibWrapper - High-level Qt interface
// ============================================================================
class CustomZlibWrapper {
public:
    // ========================================================================
    // Compression methods
    // ========================================================================
    
    /**
     * @brief Compress data using custom MASM DEFLATE implementation
     * @param data Input data to compress
     * @return Compressed data, or empty QByteArray on error
     */
    static QByteArray compress(const QByteArray& data) {
        if (data.isEmpty()) {
            qWarning() << "[CustomZlib] Cannot compress empty data";
            return QByteArray();
        }
        
        // Allocate output buffer with safety margin
        uint64_t maxCompressedSize = CustomZlibGetCompressedSize(data.size());
        QByteArray compressed(maxCompressedSize, Qt::Uninitialized);
        
        qDebug() << "[CustomZlib] Compressing" << data.size() << "bytes";
        
        int64_t compressedSize = CustomZlibCompress(
            reinterpret_cast<const uint8_t*>(data.constData()),
            static_cast<uint64_t>(data.size()),
            reinterpret_cast<uint8_t*>(compressed.data()),
            static_cast<uint64_t>(compressed.size())
        );
        
        if (compressedSize < 0) {
            qCritical() << "[CustomZlib] Compression failed with error code:" << compressedSize;
            return QByteArray();
        }
        
        compressed.resize(compressedSize);
        qInfo() << "[CustomZlib] Compressed" << data.size() << "bytes to"
                << compressedSize << "bytes (ratio:"
                << QString::number(100.0 * compressedSize / data.size(), 'f', 1) << "%)";
        
        return compressed;
    }
    
    /**
     * @brief Decompress data using custom MASM DEFLATE implementation
     * @param compressed Compressed data
     * @param maxDecompressedSize Maximum expected decompressed size (safety limit)
     * @return Decompressed data, or empty QByteArray on error
     */
    static QByteArray decompress(const QByteArray& compressed, qint64 maxDecompressedSize = 100 * 1024 * 1024) {
        if (compressed.isEmpty()) {
            qWarning() << "[CustomZlib] Cannot decompress empty data";
            return QByteArray();
        }
        
        // Estimate decompressed size
        int64_t estimatedSize = CustomZlibGetDecompressedSize(
            reinterpret_cast<const uint8_t*>(compressed.constData()),
            static_cast<uint64_t>(compressed.size())
        );
        
        if (estimatedSize < 0) {
            qCritical() << "[CustomZlib] Invalid compressed data format";
            return QByteArray();
        }
        
        // Apply safety limit
        uint64_t outputSize = qMin(static_cast<uint64_t>(estimatedSize), 
                                   static_cast<uint64_t>(maxDecompressedSize));
        
        QByteArray decompressed(outputSize, Qt::Uninitialized);
        
        qDebug() << "[CustomZlib] Decompressing" << compressed.size() << "bytes";
        
        int64_t decompressedSize = CustomZlibDecompress(
            reinterpret_cast<const uint8_t*>(compressed.constData()),
            static_cast<uint64_t>(compressed.size()),
            reinterpret_cast<uint8_t*>(decompressed.data()),
            static_cast<uint64_t>(decompressed.size())
        );
        
        if (decompressedSize < 0) {
            qCritical() << "[CustomZlib] Decompression failed with error code:" << decompressedSize;
            return QByteArray();
        }
        
        decompressed.resize(decompressedSize);
        qInfo() << "[CustomZlib] Decompressed" << compressed.size() << "bytes to"
                << decompressedSize << "bytes";
        
        return decompressed;
    }
    
    // ========================================================================
    // Utility methods
    // ========================================================================
    
    /**
     * @brief Get maximum compressed size for given input size
     * @param uncompressedSize Size of uncompressed data
     * @return Maximum possible compressed size
     */
    static qint64 getMaxCompressedSize(qint64 uncompressedSize) {
        return static_cast<qint64>(CustomZlibGetCompressedSize(uncompressedSize));
    }
    
    /**
     * @brief Check if data appears to be ZLIB compressed
     * @param data Data to check
     * @return True if data has valid ZLIB header
     */
    static bool isCompressed(const QByteArray& data) {
        if (data.size() < 2) {
            return false;
        }
        
        uint8_t cmf = static_cast<uint8_t>(data[0]);
        uint8_t flg = static_cast<uint8_t>(data[1]);
        
        // Check CMF: compression method must be 8 (DEFLATE)
        if ((cmf & 0x0F) != 8) {
            return false;
        }
        
        // Check CMF + FLG checksum
        uint16_t check = (static_cast<uint16_t>(cmf) << 8) | flg;
        if ((check % 31) != 0) {
            return false;
        }
        
        return true;
    }
    
    /**
     * @brief Get compression ratio as percentage
     * @param compressed Compressed data
     * @param uncompressed Original uncompressed data
     * @return Compression ratio (0-100)
     */
    static double getCompressionRatio(const QByteArray& compressed, const QByteArray& uncompressed) {
        if (uncompressed.isEmpty()) {
            return 0.0;
        }
        return 100.0 * static_cast<double>(compressed.size()) / static_cast<double>(uncompressed.size());
    }
};

#endif // CUSTOM_ZLIB_WRAPPER_H


// ============================================================================
// [HEADER] compression_interface.h
// FILE: D:\rawrxd\include\compression_interface.h
// ============================================================================

// [CONSOLIDATED] #pragma once

// [SYSINCLUDE] #include <vector>
// [SYSINCLUDE] #include <cstdint>
// [SYSINCLUDE] #include <memory>
// [CONSOLIDATED] #include "brutal_gzip.h"
// [CONSOLIDATED] #include "deflate_brutal_qt.hpp"

/**
 * @file compression_interface.h
 * @brief MASM-optimized compression interface for GGUF tensor loading
 * 
 * This header provides wrapper classes that integrate with:
 * - brutal_gzip.lib (MASM-optimized GZIP decompression)
 * - deflate_brutal_qt.hpp (MASM-optimized deflate with Qt integration)
 * 
 * These libraries use hand-optimized MASM kernels for maximum performance
 * on GGUF model tensor decompression.
 */

// Forward declarations
class IGZIPCompressor;
class IDeflateCompressor;

/**
 * @class ICompressionProvider
 * @brief Abstract interface for compression algorithms
 */
class ICompressionProvider {
public:
    virtual ~ICompressionProvider() = default;
    virtual bool Compress(const std::vector<uint8_t>& raw, std::vector<uint8_t>& compressed) = 0;
    virtual bool Decompress(const std::vector<uint8_t>& compressed, std::vector<uint8_t>& raw) = 0;
    virtual bool IsSupported() const = 0;
};

/**
 * @class BrutalGzipWrapper
 * @brief Wrapper around brutal_gzip.lib (MASM-optimized GZIP)
 * 
 * This class wraps the brutal_gzip library which provides:
 * - MASM-optimized decompression kernels (deflate_brutal_masm.asm)
 * - MASM-optimized compression kernels (deflate_godmode_masm.asm)
 * - Automatic CPU feature detection and kernel selection
 * - Multi-threaded decompression support
 * 
 * Performance characteristics:
 * - Decompression: ~500 MB/s on modern CPUs (AVX2/SSE2)
 * - Compression: ~200 MB/s (configurable)
 * - Memory overhead: Minimal (streaming-friendly)
 */
class BrutalGzipWrapper : public ICompressionProvider {
public:
    BrutalGzipWrapper();
    ~BrutalGzipWrapper();
    
    bool Compress(const std::vector<uint8_t>& raw, std::vector<uint8_t>& compressed) override;
    bool Decompress(const std::vector<uint8_t>& compressed, std::vector<uint8_t>& raw) override;
    bool IsSupported() const override;
    
    /**
     * @brief Get the actual MASM kernel being used
     * @return String describing the kernel (e.g., "brutal_masm", "godmode_masm", "fallback")
     */
    std::string GetActiveKernel() const;
    
    /**
     * @brief Set threading model for decompression
     * @param num_threads Number of threads to use (0 = auto-detect)
     */
    void SetThreadCount(uint32_t num_threads);

private:
    uint32_t thread_count_ = 0;  // 0 = auto-detect
    bool is_initialized_ = false;
};

/**
 * @class DeflateWrapper
 * @brief Wrapper around deflate_brutal_qt.hpp (MASM-optimized deflate)
 * 
 * This class wraps the deflate decompression with Qt integration:
 * - MASM-optimized deflate kernels (deflate_brutal_masm.asm)
 * - Full zlib/deflate compatibility
 * - Qt-friendly error handling and logging
 * - Automatic memory management
 * 
 * Performance characteristics:
 * - Decompression: ~450 MB/s on modern CPUs
 * - Memory overhead: Configurable buffers
 * - Streaming support: Per-block decompression
 */
class DeflateWrapper : public ICompressionProvider {
public:
    DeflateWrapper();
    ~DeflateWrapper();
    
    bool Compress(const std::vector<uint8_t>& raw, std::vector<uint8_t>& compressed) override;
    bool Decompress(const std::vector<uint8_t>& compressed, std::vector<uint8_t>& raw) override;
    bool IsSupported() const override;
    
    /**
     * @brief Set compression level (1-9, 9 = best compression)
     * @param level Compression level
     */
    void SetCompressionLevel(uint32_t level);
    
    /**
     * @brief Get detailed decompression statistics
     * @return Comma-separated string with stats (bytes processed, etc.)
     */
    std::string GetDecompressionStats() const;

private:
    uint32_t compression_level_ = 6;  // Default: balanced
    bool is_initialized_ = false;
    uint64_t total_decompressed_ = 0;
    uint64_t total_compressed_input_ = 0;
};

/**
 * @class CompressionFactory
 * @brief Factory for creating appropriate compression provider instances
 */
class CompressionFactory {
public:
    /**
     * @brief Create a compression provider for MASM kernels
     * @param prefer_type Preferred compression type (BRUTAL_GZIP or DEFLATE)
     * @return Shared pointer to the created provider (may fallback if not available)
     */
    static std::shared_ptr<ICompressionProvider> Create(uint32_t prefer_type = 2);  // 2 = BRUTAL_GZIP
    
    /**
     * @brief Check if a compression type is supported on this system
     * @param type Compression type to check
     * @return true if supported, false otherwise
     */
    static bool IsSupported(uint32_t type);
};

/**
 * @class CompressionStats
 * @brief Collects compression statistics for monitoring
 */
struct CompressionStats {
    uint64_t total_compressed_bytes = 0;
    uint64_t total_decompressed_bytes = 0;
    uint32_t decompression_calls = 0;
    uint32_t compression_calls = 0;
    double avg_compression_ratio = 0.0;
    
    /**
     * @brief Reset statistics
     */
    void Reset() {
        total_compressed_bytes = 0;
        total_decompressed_bytes = 0;
        decompression_calls = 0;
        compression_calls = 0;
        avg_compression_ratio = 0.0;
    }
    
    /**
     * @brief Get human-readable statistics string
     */
    std::string ToString() const;
};

