// Language Server Protocol message types
enum class LSPMessageType {
    HOVER,
    DEFINITION,
    REFERENCES,
    COMPLETION,
    SIGNATURE,
    RENAME,
    FORMAT,
    DIAGNOSTICS,
};

// LSP hover information
