// Consensus states
enum class ConsensusState : uint32_t {
    UNKNOWN = 0,
    FOLLOWER = 1,
    CANDIDATE = 2,
    LEADER = 3,
    PRE_VOTE = 4
};

// Healing status
enum class HealingStatus : uint32_t {
    IDLE = 0,
    REBUILDING = 1,
    VERIFYING = 2,
    MIGRATING = 3,
    COMPLETE = 4,
    FAILED = 5
};

// Healing task types
enum class HealingTaskType : uint32_t {
    REBUILD = 0,
    VERIFY = 1,
    MIGRATE = 2
};

// Autotune actions
enum class AutotuneAction : uint32_t {
    MAINTAIN = 0,
    SCALE_UP = 1,
    SCALE_DOWN = 2,
    REBALANCE = 3,
    THERMAL_THROTTLE = 4
};

// Autotune decision trigger
enum class AutotuneTrigger : uint32_t {
    NONE = 0,
    LOW_EFFICIENCY = 1,
    HIGH_LATENCY = 2,
    THERMAL_PRESSURE = 3,
    LOAD_IMBALANCE = 4,
    CACHE_MISS = 5
};

// gRPC method types
enum class GRPCMethodType : uint32_t {
    UNARY = 0,
    CLIENT_STREAMING = 1,
    SERVER_STREAMING = 2,
    BIDI_STREAMING = 3
};

// Prometheus metric types
enum class PrometheusMetricType : uint32_t {
    COUNTER = 0,
    GAUGE = 1,
    HISTOGRAM = 2,
    SUMMARY = 3
};

// Orchestrator states
enum class OrchestratorState : uint32_t {
    INITIALIZING = 0,
    ACTIVE = 1,
    DEGRADED = 2,
    SHUTTING_DOWN = 3
};

