    json getCompleteStats() const;
    
private:
    std::unique_ptr<AsyncStreamingEngine> m_asyncEngine;
    std::unique_ptr<BatchProcessingEngine> m_batchEngine;
    std::unique_ptr<StreamingWebServer> m_webServer;
