// [CONSOLIDATED] #pragma once

// [SYSINCLUDE] #include <string>
// [SYSINCLUDE] #include <vector>
// [SYSINCLUDE] #include <map>
// [SYSINCLUDE] #include <memory>
// [SYSINCLUDE] #include <functional>
#include <nlohmann/json.hpp>
