    // Control methods
    void startDigestion(const std::stringList& filePaths);
    void pauseDigestion();
    void resumeDigestion();
    void stopDigestion();
    
    // State queries
    State currentState() const;
    Progress currentProgress() const;
    bool isRunning() const;
