    /// Answer generation completed
    void answerGenerated(const Answer& answer);

    /// Answer verified by user
    void answerVerified();

    /// Answer marked as incorrect
    void answerIncorrect();

    /// Error occurred during Q&A
    void qaError(const std::string& error);

private:
