    void* m_vramUsageLabel;
    
    // Device selection
    void* m_deviceCombo;
    void* m_deviceInfoLabel;
    
    // Optimization options
    void* m_optimizationGroup;
    void* m_enableTensorCoresLabel;
    void* m_enableGraphsLabel;
    void* m_detectBtn;
    void* m_applyBtn;
    void* m_resetBtn;

    // ===== Backend State =====
