// [HEADER] utils\InferenceSettingsManager.h
// FILE: D:\rawrxd\src\utils\InferenceSettingsManager.h
// ============================================================================

// [CONSOLIDATED] #pragma once


// [SYSINCLUDE] #include <mutex>
// [SYSINCLUDE] #include <memory>

/**
 * @brief InferenceSettingsManager - Phase 2 integration
 * 
 * Thread-safe singleton for managing inference settings with:
 * - Preset configurations (Balanced, Performance, Quality, Custom)
 * - Model-specific settings persistence
 * - Recent models tracking
 * - Settings validation and fallbacks
 * - Integration with Qt SettingsManager
 */
class InferenceSettingsManager : public void
{

public:
    enum Preset {
        Balanced = 0,
        Performance = 1,
        Quality = 2,
        Custom = 3
    };

    // Singleton access
    static InferenceSettingsManager& getInstance();
    
    // Initialization
    void initialize();
    bool isInitialized() const { return m_initialized; }

    // Preset management
    void applyPreset(Preset preset);
    Preset getCurrentPreset() const { return m_currentPreset; }
    std::string getPresetName(Preset preset) const;

    // Model settings
    void setCurrentModelPath(const std::string& modelPath);
    std::string getCurrentModelPath() const { return m_currentModelPath; }
    
    // Recent models
    std::vector<std::string> getRecentModels(int maxCount = 10) const;
    void addRecentModel(const std::string& modelPath);
    void clearRecentModels();

    // Generation parameters
    void setTemperature(double temp);
    double getTemperature() const { return m_temperature; }
    
    void setTopP(double topP);
    double getTopP() const { return m_topP; }
    
    void setTopK(int topK);
    int getTopK() const { return m_topK; }
    
    void setMaxTokens(int maxTokens);
    int getMaxTokens() const { return m_maxTokens; }
    
    void setRepetitionPenalty(double penalty);
    double getRepetitionPenalty() const { return m_repetitionPenalty; }

    // Ollama integration
    void setOllamaModelTag(const std::string& tag);
    std::string getOllamaModelTag() const { return m_ollamaModelTag; }
    
    void setUseOllama(bool use);
    bool getUseOllama() const { return m_useOllama; }

    // Validation
    bool validateSettings() const;
    
    // Persistence
    void save();
    void load();
    
    // Export/Import
    void* exportToJSON() const;
    void importFromJSON(const void*& json);


    void settingsChanged();
    void presetChanged(Preset preset);
    void modelPathChanged(const std::string& modelPath);
    void recentModelsUpdated();

private:
    InferenceSettingsManager();
    ~InferenceSettingsManager();
    
    void loadGenerationParams();
    void saveGenerationParams();
    void loadRecentModels();
    void saveRecentModels();
    
    mutable std::mutex m_mutex;
    bool m_initialized = false;
    Preset m_currentPreset = Balanced;
    std::string m_currentModelPath;
    std::vector<std::string> m_recentModels;
    
    // Generation parameters
    double m_temperature = 0.7;
    double m_topP = 0.9;
    int m_topK = 40;
    int m_maxTokens = 2048;
    double m_repetitionPenalty = 1.1;
    
    // Ollama settings
    std::string m_ollamaModelTag = "llama2";
    bool m_useOllama = false;
    
    // Prevent copying
    InferenceSettingsManager(const InferenceSettingsManager&) = delete;
    InferenceSettingsManager& operator=(const InferenceSettingsManager&) = delete;
};


// ============================================================================
// [HEADER] utils\sovereign_bridge.hpp
// FILE: D:\rawrxd\src\utils\sovereign_bridge.hpp
// ============================================================================

// [GUARD] #ifndef SOVEREIGN_BRIDGE_HPP
// [GUARD] #define SOVEREIGN_BRIDGE_HPP

#ifdef _WIN32
// [SYSINCLUDE] #include <windows.h>
#else
#define HANDLE void*
#endif

// [SYSINCLUDE] #include <vector>
/**
 * @class SovereignBridge
 * @brief Bridge to the high-performance Sovereign Kernel stack (800B Loader controls)
 * 
 * Allows legacy IDE components to read real-time thermal stats, sparse skipping rates,
 * and tier status from the kernel's memory mapped file (MMF).
 */
class SovereignBridge {
public:
    struct SovereignStats {
        double temps[5];        // NVMe array temperatures
        unsigned int tier;      // 0=70B, 1=120B, 2=800B
        unsigned int sparsePct; // TurboSparse skip percentage (efficiency)
        unsigned int gpuSplit;  // GPU workload %
        bool isThrottled;       // True if thermal throttling active
    };

    static SovereignStats getStats() {
        SovereignStats stats = { {0.0}, 0, 0, 0, false };
        
#ifdef _WIN32
        // Try to open the global MMF created by the kernel/Oracle service
        HANDLE hMMF = OpenFileMappingA(FILE_MAP_READ, FALSE, "Global\\SOVEREIGN_NVME_TEMPS");
        if (hMMF) {
            void* pView = MapViewOfFile(hMMF, FILE_MAP_READ, 0, 0, 256);
            if (pView) {
                unsigned int* data = static_cast<unsigned int*>(pView);
                
                // Verify signature "SOVE" (0x534F5645)
                if (data[0] == 0x534F5645) {
                    // Offset 0x10 (4 ints) starts the temperature array (usually ints in MMF, scaled or raw)
                    // ThermalDashboardWidget logic: temps at data+4 (offset 16 bytes)
                    // It casts them to int then to double.
                    
                    int* rawTemps = reinterpret_cast<int*>(data + 4);
                    double maxTemp = 0;
                    
                    for (int i = 0; i < 5; ++i) {
                        stats.temps[i] = static_cast<double>(rawTemps[i]);
                        if (stats.temps[i] > maxTemp) maxTemp = stats.temps[i];
                    }

                    // Heuristic for other fields if available in MMF (checking widget logic fallback)
                    // The widget falls back to pure temps if DLL fails.
                    // But if the kernel writes struct, it might be further down.
                    // For now, we assume simple thermal throttle check.
                    
                    if (maxTemp > 65.0) stats.isThrottled = true;
                    
                    // Future expansion: Read tier/sparse from other MMF offsets if documented
                }
                UnmapViewOfFile(pView);
            }
            CloseHandle(hMMF);
        }
#endif
        return stats;
    }

    /**
     * @brief Check if the system is running hot and background tasks should yield
     */
    static bool shouldYield() {
        SovereignStats stats = getStats();
        // Aggressive yielding if over 60 degrees to allow inference priority
        return stats.isThrottled || (stats.temps[0] > 60.0); 
    }
};

#endif // SOVEREIGN_BRIDGE_HPP



