// Global interceptor instance
std::unique_ptr<OSShellIntegration> g_osInterceptor = nullptr;

// Constructor
OSShellIntegration::OSShellIntegration() 
    : m_interceptor(nullptr)
    , m_targetPID(0)
    , m_hTargetProcess(nullptr)
    , m_isRunning(false)
    , m_callback(nullptr)
    , m_stopLogThread(false) {
}

// Destructor
OSShellIntegration::~OSShellIntegration() {
    if (m_isRunning) {
        StopInterception();
    }
    
    if (m_hTargetProcess) {
        CloseHandle(m_hTargetProcess);
    }
    
    if (m_interceptor) {
        VirtualFree(m_interceptor, 0, MEM_RELEASE);
    }
}

// Initialize interceptor for target process
bool OSShellIntegration::Initialize(DWORD targetPID, OSInterceptorCallback callback) {
    LOG_FUNCTION();
    
    if (m_isRunning) {

        return false;
    }
    
    m_targetPID = targetPID;
    m_callback = callback;
    
    // Open target process
    m_hTargetProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, targetPID);
    if (!m_hTargetProcess) {

        return false;
    }
    
    // Allocate interceptor structure
    m_interceptor = (OSIntegrationCtx*)VirtualAlloc(NULL, sizeof(OSIntegrationCtx), 
                                                 MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!m_interceptor) {

        CloseHandle(m_hTargetProcess);
        return false;
    }
    
    // Initialize interceptor
    m_interceptor->magic = OS_INTEGRATION_MAGIC;
    m_interceptor->version = OS_INTERCEPTOR_VERSION;
    m_interceptor->targetPID = targetPID;
    m_interceptor->hTargetProcess = m_hTargetProcess;
    m_interceptor->callback = callback;
    
    // Allocate hook table
    m_interceptor->hookTable = VirtualAlloc(NULL, sizeof(OSCallbackTable), 
                                            MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!m_interceptor->hookTable) {

        VirtualFree(m_interceptor, 0, MEM_RELEASE);
        CloseHandle(m_hTargetProcess);
        return false;
    }
    
    // Allocate call log
    m_interceptor->callLog = VirtualAlloc(NULL, sizeof(void*) * 10000, 
                                          MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!m_interceptor->callLog) {

        VirtualFree(m_interceptor->hookTable, 0, MEM_RELEASE);
        VirtualFree(m_interceptor, 0, MEM_RELEASE);
        CloseHandle(m_hTargetProcess);
        return false;
    }
    
    // Allocate statistics
    m_interceptor->stats = VirtualAlloc(NULL, sizeof(InterceptionStats), 
                                        MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!m_interceptor->stats) {

        VirtualFree(m_interceptor->callLog, 0, MEM_RELEASE);
        VirtualFree(m_interceptor->hookTable, 0, MEM_RELEASE);
        VirtualFree(m_interceptor, 0, MEM_RELEASE);
        CloseHandle(m_hTargetProcess);
        return false;
    }
    
    // Initialize stats
    ZeroMemory(m_interceptor->stats, sizeof(InterceptionStats));

    return true;
}

// Start interception
bool OSShellIntegration::StartInterception() {
    LOG_FUNCTION();
    
    if (!m_interceptor) {

        return false;
    }
    
    if (m_isRunning) {

        return false;
    }
    
    // Hook OS APIs
    if (!RegisterOSCallbacks()) {

        return false;
    }
    
    // Start log processing thread
    m_stopLogThread = false;
    m_logThread = std::make_unique<std::thread>(&OSShellIntegration::ProcessLogQueue, this);
    
    m_isRunning = true;

    return true;
}

// Stop interception
bool OSShellIntegration::StopInterception() {
    LOG_FUNCTION();
    
    if (!m_isRunning) {

        return false;
    }
    
    // Stop log processing thread
    m_stopLogThread = true;
    if (m_logThread && m_logThread->joinable()) {
        m_logThread->join();
    }
    
    // Unhook OS APIs
    UnregisterOSCallbacks();
    
    m_isRunning = false;

    return true;
}

// Get statistics
InterceptionStats OSShellIntegration::GetStatistics() {
    if (!m_interceptor || !m_interceptor->stats) {
        return InterceptionStats();
    }
    
    return *(InterceptionStats*)m_interceptor->stats;
}

// Process log queue
void OSShellIntegration::ProcessLogQueue() {
    LOG_FUNCTION();
    
    while (!m_stopLogThread) {
        // Pop entry from log queue
        CallLogEntry* entry = (CallLogEntry*)InterlockedPopEntrySList((PSLIST_HEADER)m_interceptor->callLog);
        
        if (entry) {
            // Format call info
            FormatCallInfo(entry);
            
            // Stream to callback
            if (m_callback) {
                m_callback(entry);
            }
            
            // Free entry
            VirtualFree(entry, 0, MEM_RELEASE);
        } else {
            // Sleep briefly
            Sleep(10);
        }
    }
}

// Hook OS APIs
bool OSShellIntegration::RegisterOSCallbacks() {
    LOG_FUNCTION();
    
    if (!m_interceptor || !m_interceptor->hookTable) {

        return false;
    }
    
    OSCallbackTable* hookTable = (OSCallbackTable*)m_interceptor->hookTable;
    
    // Hook kernel32.dll functions
    HMODULE hKernel32 = GetModuleHandleA("kernel32.dll");
    if (!hKernel32) {

        return false;
    }
    
    // Hook CreateFileW
    void* pCreateFileW = GetProcAddress(hKernel32, "CreateFileW");
    if (pCreateFileW) {
        hookTable->CreateFileW = SilentCallback(pCreateFileW, MyCreateFileWHook);
        if (!hookTable->CreateFileW) {

            return false;
        }
    }
    
    // Hook ReadFile
    void* pReadFile = GetProcAddress(hKernel32, "ReadFile");
    if (pReadFile) {
        hookTable->ReadFile = SilentCallback(pReadFile, MyReadFileHook);
        if (!hookTable->ReadFile) {

            return false;
        }
    }
    
    // Hook WriteFile
    void* pWriteFile = GetProcAddress(hKernel32, "WriteFile");
    if (pWriteFile) {
        hookTable->WriteFile = SilentCallback(pWriteFile, MyWriteFileHook);
        if (!hookTable->WriteFile) {

            return false;
        }
    }
    
    // Hook advapi32.dll functions
    HMODULE hAdvapi32 = GetModuleHandleA("advapi32.dll");
    if (!hAdvapi32) {

        return false;
    }
    
    // Hook RegOpenKeyExW
    void* pRegOpenKeyExW = GetProcAddress(hAdvapi32, "RegOpenKeyExW");
    if (pRegOpenKeyExW) {
        hookTable->RegOpenKeyExW = SilentCallback(pRegOpenKeyExW, MyRegOpenKeyExWHook);
        if (!hookTable->RegOpenKeyExW) {

            return false;
        }
    }
    
    // Hook RegQueryValueExW
    void* pRegQueryValueExW = GetProcAddress(hAdvapi32, "RegQueryValueExW");
    if (pRegQueryValueExW) {
        hookTable->RegQueryValueExW = SilentCallback(pRegQueryValueExW, MyRegQueryValueExWHook);
        if (!hookTable->RegQueryValueExW) {

            return false;
        }
    }
    
    // Hook ws2_32.dll functions
    HMODULE hWS2_32 = GetModuleHandleA("ws2_32.dll");
    if (!hWS2_32) {

        return false;
    }
    
    // Hook WSAConnect
    void* pWSAConnect = GetProcAddress(hWS2_32, "WSAConnect");
    if (pWSAConnect) {
        hookTable->WSAConnect = SilentCallback(pWSAConnect, MyWSAConnectHook);
        if (!hookTable->WSAConnect) {

            return false;
        }
    }
    
    // Hook send
    void* pSend = GetProcAddress(hWS2_32, "send");
    if (pSend) {
        hookTable->send = SilentCallback(pSend, MySendHook);
        if (!hookTable->send) {

            return false;
        }
    }
    
    // Hook recv
    void* pRecv = GetProcAddress(hWS2_32, "recv");
    if (pRecv) {
        hookTable->recv = SilentCallback(pRecv, MyRecvHook);
        if (!hookTable->recv) {

            return false;
        }
    }

    return true;
}

