// PowerShell Panel Control IDs
#define IDC_PS_PANEL_CONTAINER 5000
#define IDC_PS_OUTPUT 5001
#define IDC_PS_INPUT 5002
#define IDC_PS_TOOLBAR 5003
#define IDC_PS_STATUSBAR 5004
