void PrintHelp() {
    std::cout << R"(RawrXD Agent v1.0
USAGE: RawrXD_Agent.exe [OPTIONS]
OPTIONS:
    --help, -h      Show this help
    --version, -v   Show version
    --list, -l      List models
    --port <n>      Server port (default: 11434)
    --host <ip>     Bind address (default: 127.0.0.1)
)";
}

void PrintVersion() {
    std::cout << "RawrXD Agent v1.0.0 (Qt-Free)\n";
}

int wmain(int argc, wchar_t* argv[]) {
    if (argc < 2) {
        // Default: start server
        std::cout << "Starting server on 127.0.0.1:11434\n";
        // HttpServer server("127.0.0.1", 11434); server.Run();
        return 0;
    }
    
    std::wstring arg = argv[1];
    if (arg == L"--help" || arg == L"-h") { PrintHelp(); return 0; }
    if (arg == L"--version" || arg == L"-v") { PrintVersion(); return 0; }
    if (arg == L"--list" || arg == L"-l") { 
        std::cout << "Models: (enumerate from ModelManager)\n"; 
        return 0; 
    }
    
    int port = 11434;
    std::string host = "127.0.0.1";
    
    for (int i = 1; i < argc; i++) {
        std::wstring a = argv[i];
        if ((a == L"--port" || a == L"-p") && i + 1 < argc) 
            port = _wtoi(argv[++i]);
        if ((a == L"--host") && i + 1 < argc) 
            host = std::string(argv[++i], argv[++i] + wcslen(argv[i]));
    }
    
    std::cout << "Starting server on " << host << ":" << port << "\n";
    return 0;
}


// ============================================================================
// [SOURCE] agent\agent_main.cpp
// FILE: D:\rawrxd\src\agent\agent_main.cpp
// ============================================================================

// [CONSOLIDATED] #include "planner.hpp"
// [CONSOLIDATED] #include "self_patch.hpp"
// [CONSOLIDATED] #include "release_agent.hpp"
// [CONSOLIDATED] #include "meta_learn.hpp"
// [CONSOLIDATED] #include "self_test_gate.hpp"
#include <nlohmann/json.hpp>
// [SYSINCLUDE] #include <iostream>
// [SYSINCLUDE] #include <string>
// [SYSINCLUDE] #include <vector>
// [SYSINCLUDE] #include <cstdlib>

using json = nlohmann::json;

int main(int argc, char *argv[]) {
    if (argc < 2) {
        
        return 1;
    }

    std::string wish;
    for (int i = 1; i < argc; ++i) {
        if (i > 1) {
            wish += " ";
        }
        wish += argv[i];
    }

    // ============================================================================
    // Step 1: Plan
    // ============================================================================
    Planner planner;
    json tasks = planner.plan(wish);

    if (!tasks.is_array() || tasks.empty()) {
        
        return 1;
    }

    // ============================================================================
    // Step 2: Execute
    // ============================================================================
    SelfUpdate patch;
    ReleaseAgent rel;
    MetaLearn ml;

    bool success = true;
    size_t taskCount = 0;
    size_t failureCount = 0;

    for (const auto& task : tasks) {
        if (!task.is_object()) {
            continue;
        }
        std::string type = task.value("type", "");
        ++taskCount;

        if (type == "add_kernel") {
            success = patch.addKernel(task.value("target", ""), task.value("template", ""));
        } else if (type == "add_cpp") {
            std::string deps;
            if (task.contains("deps") && task["deps"].is_array()) {
                for (const auto& val : task["deps"]) {
                    if (!deps.empty()) {
                        deps += ",";
                    }
                    deps += val.get<std::string>();
                }
            } else {
                deps = task.value("deps", "");
            }
            success = patch.addCpp(task.value("target", ""), deps);
        } else if (type == "build") {
            std::string cmd = "cmake --build build --config Release";
            std::string target = task.value("target", "");
            if (!target.empty()) {
                cmd += " --target " + target;
            }
            int rc = std::system(cmd.c_str());
            success = (rc == 0);
        } else if (type == "hot_reload") {
            success = patch.hotReload();
        } else if (type == "bump_version") {
            success = rel.bumpVersion(task.value("part", ""));
        } else if (type == "tag") {
            success = rel.tagAndUpload();
        } else if (type == "tweet") {
            success = rel.tweet(task.value("text", ""));
        } else if (type == "meta_learn") {
            success = ml.record(
                task.value("quant", ""),
                task.value("kernel", ""),
                task.value("gpu", ""),
                task.value("tps", 0.0),
                task.value("ppl", 0.0)
            );
        } else if (type == "bench" || type == "bench_all") {
            success = true;
        }

        if (!success) {
            failureCount++;
            return 1;
        }
    }

    // ============================================================================
    // Summary
    // ============================================================================

    std::string suggested = ml.suggestQuant();
    (void)suggested;
    (void)taskCount;
    (void)failureCount;

    return 0;
}


