{
    if (m_usingStreaming && m_streamingLoader)
    {
        try
        {
            m_streamingLoader->LoadZone(zoneName);
            return true;
        }
        catch (const std::exception& e)
        {
            ErrorReporter::report("Failed to preload zone " + zoneName + ": " + e.what(), nullptr);
            return false;
        }
    }

    return false;
}

