        result = Titan_HAL_Init_Real();
        g_init_metrics.hal_time = GetTickCount() - phase_start;
        
        if (result != 0) {
            LogMessage(LOG_ERROR, "[INIT FAILED] HAL initialization failed with code: %d", result);
            goto INIT_FAILED;
        }
        
