void InitializeSwarmMind(const char* model_path) {
    DirectIO_Init(&g_pDirectIOCtx, model_path);
    g_zoneBuffer = _aligned_malloc(8LL * 1024 * 1024 * 1024, 4096); // 8GB Swarm Memory
    RefreshBurstPlan(32);
}


