bool IDEWindow::Initialize(HINSTANCE hInstance)
{
    hInstance_ = hInstance;
    
    // Initialize common controls
    INITCOMMONCONTROLSEX icex;
    icex.dwSize = sizeof(INITCOMMONCONTROLSEX);
    icex.dwICC = ICC_WIN95_CLASSES | ICC_BAR_CLASSES | ICC_TREEVIEW_CLASSES;
    InitCommonControlsEx(&icex);
    
    // Load RichEdit library
    LoadLibraryW(L"Msftedit.dll");
    
    CreateMainWindow(hInstance);
    
    if (!hwnd_) {
        return false;
    }
    
    ShowWindow(hwnd_, SW_SHOW);
    UpdateWindow(hwnd_);
    
    return true;
}

void IDEWindow::CreateMainWindow(HINSTANCE hInstance)
{
    // Register window class
    WNDCLASSEXW wc = {};
    wc.cbSize = sizeof(WNDCLASSEXW);
    wc.style = CS_HREDRAW | CS_VREDRAW;
    wc.lpfnWndProc = WindowProc;
    wc.hInstance = hInstance;
    wc.hCursor = LoadCursor(nullptr, IDC_ARROW);
    wc.hbrBackground = (HBRUSH)(COLOR_WINDOW + 1);
    wc.lpszClassName = IDE_WINDOW_CLASS;
    wc.hIcon = LoadIcon(nullptr, IDI_APPLICATION);
    wc.hIconSm = LoadIcon(nullptr, IDI_APPLICATION);
    
    RegisterClassExW(&wc);
    
    // Create main window
    hwnd_ = CreateWindowExW(
        0,
        IDE_WINDOW_CLASS,
        L"RawrXD PowerShell IDE - C++ Edition",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT,
        1400, 900,
        nullptr,
        nullptr,
        hInstance,
        this
    );
    
    if (hwnd_) {
        CreateMenuBar();
        CreateToolBar();
        CreateStatusBar();
        CreateEditorControl();
        CreateFileExplorer();
        CreateTerminalPanel();
        CreateOutputPanel();
        CreateTabControl();
        LoadSession();
    }
}

