void AlertSystem::startMonitoring()
{

    m_healthCheckTimer->start(m_config.healthCheckInterval);
    m_performanceTimer->start(m_config.performanceCheckInterval);
    m_alertCleanupTimer->start(3600000);  // Cleanup every hour
    
    // Run initial checks
    checkSystemHealth();
    monitorPerformance();
    
    monitoringStarted();
}

