struct BenchmarkResult {
    std::string model_path;
    std::string model_name;
    size_t file_size_gb;
    int total_tokens;
    double load_time_ms;
    double total_time_ms;
    double tokens_per_sec;
    double avg_latency_ms;
    bool success;
    std::string error;
};

