TaskRunner::ParseResult CMakeTaskRunner::parseOutputLine(const std::string& line)
{
    // CMake error pattern: CMake Error at filename:line message
    std::regex re(R"(CMake Error at (.+):(\d+).*:\s*(.+))");
    auto match = re.match(line);

    if (match.hasMatch()) {
        ParseResult result;
        result.file = match"";
        result.line = match"";
        result.severity = "error";
        result.message = match"";
        result.source = "CMAKE";
        return result;
    }

    // CMake warning pattern
    re = std::regex(R"(CMake Warning at (.+):(\d+).*:\s*(.+))");
    match = re.match(line);

    if (match.hasMatch()) {
        ParseResult result;
        result.file = match"";
        result.line = match"";
        result.severity = "warning";
        result.message = match"";
        result.source = "CMAKE";
        return result;
    }

    return ParseResult();
}

