void FindWidget::onSearchTextChanged() {
    clearHighlights();
    
    if (searchText().empty()) {
        m_matches.clear();
        m_currentMatchIndex = -1;
        m_matchCountLabel->setText("No matches");
        return;
    }
    
    addToSearchHistory(searchText());
    
    findAll();
    highlightAllMatches();
    updateMatchCount();
    
    // Auto-select first match
    if (!m_matches.empty()) {
        findNext();
    }
}

